/**
 * POST /api/v1/aliases - Bitwarden "Forwarded email alias" generator
 *
 * Bitwarden's addy.io forwarder posts `{ domain, description }` to
 * `{server URL}/api/v1/aliases` and reads `data.email` from a 200/201 reply, so
 * with the server URL set to https://anon.li it lands here. Bitwarden owns the
 * request shape, which is why this lives beside the native `/api/v1/alias`.
 *
 * `description` ("Website: example.com. Generated by Bitwarden.") is dropped,
 * never stored: alias labels are vault-encrypted, and the server must not learn
 * which site an alias was made for.
 *
 * Authentication: API key only (Bearer ak_...)
 */

import { z } from "zod"

import { apiError, apiSuccessWithStatus, ErrorCodes, zodErrorToDetails } from "@/lib/api-response"
import { withPolicy, scopeFromContext } from "@/lib/route-policy"
import { AliasService } from "@/lib/services/alias"
import { toAddyFormat } from "../alias/_utils"

export const dynamic = "force-dynamic"

// Not strict: unknown keys (including `description`) are stripped rather than
// rejected, so a new field in Bitwarden's request can't break generation.
const bitwardenAliasSchema = z.object({
    domain: z.string().trim().toLowerCase().max(253).optional().default("anon.li"),
})

const createAlias = withPolicy(
    {
        auth: "api_key",
        organizationAccess: "subscribed",
        apiQuota: "alias",
        requireCsrf: true,
        checkBan: "alias",
        rateLimit: "aliasCreate",
    },
    async (ctx) => {
        if (!ctx.userId) {
            return apiError("Unauthorized", ErrorCodes.UNAUTHORIZED, ctx.requestId, 401)
        }

        const body: unknown = await ctx.request.json().catch(() => null)
        const validation = bitwardenAliasSchema.safeParse(body)
        if (!validation.success) {
            return apiError(
                "Validation failed",
                ErrorCodes.VALIDATION_ERROR,
                ctx.requestId,
                400,
                zodErrorToDetails(validation.error),
            )
        }

        const alias = await AliasService.createAlias(scopeFromContext(ctx), {
            domain: validation.data.domain,
            format: "RANDOM",
        })

        return apiSuccessWithStatus(toAddyFormat({
            id: alias.id,
            email: alias.email,
            active: alias.active,
            encryptedLabel: alias.encryptedLabel,
            encryptedNote: alias.encryptedNote,
            createdAt: alias.createdAt,
            updatedAt: alias.updatedAt,
        }), ctx.requestId, 201)
    },
)

/**
 * Bitwarden shows a failed reply's top-level `error`/`message` string. Our
 * envelope nests the message inside an `error` object, which it would render as
 * "[object Object]", so hoist the message to where Bitwarden looks for it.
 */
async function withBitwardenError(response: Response): Promise<Response> {
    if (response.ok) return response

    const body = await response.clone().json().catch(() => null) as { error?: { message?: unknown } } | null
    const message = body?.error?.message
    if (typeof message !== "string") return response

    const headers = new Headers(response.headers)
    headers.delete("content-length")
    return new Response(JSON.stringify({ message }), { status: response.status, headers })
}

export async function POST(request: Request) {
    return withBitwardenError(await createAlias(request))
}
